-- ── §2–§10 Apply (one block, so a migrations-only replay can skip it as a whole) ────────────────────────
DO $apply$
DECLARE
  v_bad text; v_n bigint; v_have bigint; v_marker boolean := pg_catalog.to_regclass('backup._backup_food_items_053') IS NOT NULL;
BEGIN
  -- production vs migrations-only replay: from the rows 058 touches, cross-checked with 053's backup marker (053
  -- creates it only when it ran with production data); never from a row count (pending 055 adds 11,986 verified
  -- rows on a replay too). Every other combination RAISEs instead of silently running as a replay.
  SELECT count(*), count(fi.id) INTO v_n, v_have FROM (SELECT old_id AS id FROM _plan058 UNION SELECT id FROM _src058) x
    LEFT JOIN public.food_items fi ON fi.id = x.id;
  IF v_have = 0 AND NOT v_marker THEN
    UPDATE _state058 SET go = false;
    RAISE NOTICE '058: no production food rows here (migrations-only replay): no row changed';
    RETURN;
  END IF;
  IF v_have < v_n THEN
    RAISE EXCEPTION '058: only % of the % rows it supersedes or copies exist (partial state?; 053 marker %)', v_have, v_n,
      CASE WHEN v_marker THEN 'present' ELSE 'absent' END;
  END IF;
  IF NOT v_marker THEN
    RAISE EXCEPTION '058: the rows it supersedes or copies are here but backup._backup_food_items_053 is missing (053 rolled back, or its backup renamed or cleaned up)';
  END IF;

  -- §3 compare-and-swap against data/batch2/snapshot.json: any drift aborts with the rows listed
  SELECT string_agg(left(p.old_id::text, 8) || ' ' || coalesce(fi.status, 'missing') || '/' ||
                    coalesce(coalesce(fi.normalized_name, fi.parked_normalized_name), '-') || '/' ||
                    coalesce(fi.calories_per_100g::text, '-'), '; ' ORDER BY p.old_id) INTO v_bad
    FROM _plan058 p LEFT JOIN public.food_items fi ON fi.id = p.old_id
   WHERE fi.id IS NULL OR fi.created_by IS NOT NULL OR fi.normalized_name IS DISTINCT FROM p.expect_key
      OR fi.status IS DISTINCT FROM p.expect_status OR fi.source IS DISTINCT FROM p.source OR fi.fdc_id IS DISTINCT FROM p.fdc_id
      OR (fi.calories_per_100g, fi.protein_per_100g, fi.carbs_per_100g, fi.fat_per_100g, fi.fiber_per_100g)
         IS DISTINCT FROM (p.kcal, p.protein, p.carbs, p.fat, p.fiber)
      OR fi.portions IS DISTINCT FROM p.portions;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: rows changed since the snapshot (re-take data/batch2/snapshot.json and regenerate): %', v_bad;
  END IF;
  SELECT string_agg(left(p.old_id::text, 8) || ' has ' || c.n || ' (snapshot ' || p.expect_memory || ')', ', ') INTO v_bad
    FROM _plan058 p CROSS JOIN LATERAL (SELECT count(*) n FROM public.user_food_memory m WHERE m.food_item_id = p.old_id) c
   WHERE c.n <> p.expect_memory;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: memory pointers at superseded rows changed since the snapshot (re-take it and regenerate): %', v_bad;
  END IF;
  -- 054 food-scoped personal calibrations key on food_item_id: one on a superseded row would stop applying (none today)
  SELECT string_agg(left(c.food_item_id::text, 8) || ' x' || c.n, ', ') INTO v_bad FROM (
    SELECT food_item_id, count(*) n FROM public.user_portion_calibrations
     WHERE scope = 'food' AND revoked_at IS NULL AND food_item_id IN (SELECT old_id FROM _plan058 UNION SELECT id FROM _new058)
     GROUP BY 1) c;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: active food-scoped portion calibrations on rows it supersedes (move them first): %', v_bad;
  END IF;
  SELECT string_agg(left(s.id::text, 8), ', ' ORDER BY s.id) INTO v_bad
    FROM _src058 s LEFT JOIN public.food_items fi ON fi.id = s.id
    LEFT JOIN public.food_derivation_items di ON di.food_item_id = s.id
    LEFT JOIN public.food_derivations d ON d.id = di.derivation_id
   WHERE fi.id IS NULL OR fi.status <> 'verified' OR fi.created_by IS NOT NULL OR fi.normalized_name IS DISTINCT FROM s.expect_key
      OR (fi.calories_per_100g, fi.protein_per_100g, fi.carbs_per_100g, fi.fat_per_100g, fi.fiber_per_100g)
         IS DISTINCT FROM (s.kcal, s.protein, s.carbs, s.fat, s.fiber)
      OR fi.portions IS DISTINCT FROM s.portions OR di.derivation_id IS DISTINCT FROM s.derivation_id
      OR (d.kcal, d.protein_g, d.carbs_g, d.fat_g, d.fiber_g) IS DISTINCT FROM (s.kcal, s.protein, s.carbs, s.fat, s.fiber);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: copy sources changed since the snapshot (or lost their 053 derivation): %', v_bad;
  END IF;
  SELECT string_agg(a.alias || ' -> ' || coalesce(left(fa.food_item_id::text, 8), 'absent'), ', ' ORDER BY a.alias) INTO v_bad
    FROM _alias058 a LEFT JOIN public.food_aliases fa ON fa.alias = a.alias
   WHERE fa.food_item_id IS DISTINCT FROM a.expect_target;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: food_aliases changed since the snapshot: %', v_bad;
  END IF;
  SELECT string_agg(fi.normalized_name || ' held by ' || left(fi.id::text, 8), ', ') INTO v_bad
    FROM public.food_items fi JOIN _new058 nw ON fi.normalized_name = nw.key
   WHERE fi.id NOT IN (SELECT old_id FROM _plan058);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: a key 058 assigns is held by a row outside the plan: %', v_bad;
  END IF;
  SELECT string_agg(fa.alias, ', ') INTO v_bad FROM public.food_aliases fa JOIN _new058 nw ON nw.key = fa.alias
   WHERE fa.alias NOT IN (SELECT alias FROM _alias058 WHERE kind = 'retire');
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: an alias equals a key 058 assigns and is not planned to retire: %', v_bad;
  END IF;
  -- A new id may already exist only as this migration's own rolled-back row with unchanged facts (re-apply).
  SELECT string_agg(left(fi.id::text, 8), ', ') INTO v_bad
    FROM public.food_items fi JOIN _new058 nw ON nw.id = fi.id
   WHERE fi.status <> 'quarantined' OR fi.status_reason IS DISTINCT FROM 'reviewed:rollback_058'
      OR (fi.source, fi.name, fi.external_id, fi.fdc_id, fi.calories_per_100g, fi.protein_per_100g, fi.carbs_per_100g,
          fi.fat_per_100g, fi.fiber_per_100g, fi.portions, fi.created_by)
         IS DISTINCT FROM (nw.source, nw.name, nw.external_id, nw.fdc_id, nw.kcal, nw.protein, nw.carbs, nw.fat,
                           nw.fiber, nw.portions, NULL::uuid);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: generated ids already exist with other facts (bump the calc version for new numbers): %', v_bad;
  END IF;
  SELECT string_agg(left(pu.id::text, 8), ', ') INTO v_bad FROM public.portion_units pu
   WHERE pu.id IN (SELECT id FROM _pu058) OR pu.food_item_id IN (SELECT id FROM _new058);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: portion_units rows already exist for the new rows: %', v_bad;
  END IF;
  SELECT string_agg(left(m.food_item_id::text, 8), ', ') INTO v_bad FROM public.portion_category_map m
   WHERE m.food_item_id IN (SELECT id FROM _new058);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: portion_category_map rows already exist for the new rows: %', v_bad;
  END IF;
  SELECT string_agg(m.category, ', ') INTO v_bad FROM (SELECT DISTINCT category FROM _map058) m
   WHERE NOT EXISTS (SELECT 1 FROM public.portion_categories c WHERE c.category = m.category);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '058: portion categories missing (054 not applied as generated?): %', v_bad;
  END IF;

  -- §4 backups (schema backup has no API-role access since 050). The memory backup holds user ids: drop all three
  --    in a later reviewed migration once 058 has settled.
  CREATE TABLE backup._backup_food_items_058 AS
    SELECT fi.* FROM public.food_items fi WHERE fi.id IN (SELECT old_id FROM _plan058 UNION SELECT id FROM _src058);
  CREATE TABLE backup._backup_food_aliases_058 AS TABLE public.food_aliases;
  CREATE TABLE backup._backup_user_food_memory_058 AS
    SELECT m.* FROM public.user_food_memory m WHERE m.food_item_id IN (SELECT old_id FROM _plan058);
  REVOKE ALL ON backup._backup_food_items_058, backup._backup_food_aliases_058, backup._backup_user_food_memory_058
    FROM PUBLIC, anon, authenticated, service_role;
  COMMENT ON TABLE backup._backup_food_items_058 IS
    'food_items rows 058 quarantined or copied, as they were before it. Source for supabase/rollback/058_recalc_indian_v2_down.sql.';
  COMMENT ON TABLE backup._backup_user_food_memory_058 IS
    'user_food_memory rows that pointed at a 058-quarantined row. Holds user ids: drop in a later reviewed migration.';

