nnum)", "role": "kept", "water_g": 0.24}, {"as_written": "Mustard seeds .25 tsp", "code": "H013", "g": 0.5, "g_as_written": null, "i": 10, "label": "Mustard seeds .25 tsp", "name": "Mustard seeds (Brassica nigra)", "role": "kept", "water_g": 0.03}, {"as_written": "Red chilli powder .167 tsp", "code": "G516", "g": 0.34, "g_as_written": null, "i": 11, "label": "Red chilli powder .167 tsp", "name": "Chilli powder", "role": "kept", "water_g": 0.12}, {"as_written": "Lemon 5 g", "code": "E520", "g": 5.0, "g_as_written": null, "i": 12, "label": "Lemon 5 g", "name": "Lemons, flesh only, raw, weighed with peel and pips", "role": "kept", "water_g": 4.85}, {"as_written": "Oil 15 g", "code": "T508", "g": 6.23, "g_as_written": 15.0, "i": 13, "label": "Oil, sunflower: cut from INDB''s 15 g per 40 g rava so the dish''s fat is 12.5% of its dry matter, as measured in Pune lab dish 101 (rava upma, F 6.5 g at 48.0% water)", "name": "Oil, sunflower", "role": "edited", "water_g": 0.0}, {"as_written": "Salt .25 tsp", "code": "G528", "g": 0.5, "g_as_written": null, "i": 14, "label": "Salt .25 tsp", "name": "Salt", "role": "kept", "water_g": 0.0}, {"as_written": "Water 100 ml", "code": "K505", "g": 100.0, "g_as_written": null, "i": 15, "label": "Water 100 ml", "name": "Water, distilled", "role": "kept", "water_g": 100.0}]'::jsonb,
     '6a1261d97ad5bda784f42181435c6138176c7acddb410bf653ba37aa3ebdba3f', 'Rava upma at the Pune lab dish 101 anchor (48.0% water), with INDB BFP039''s oil cut so the dish''s fat is the lab''s 12.5% of dry matter (founder oil rule, spec (i)2). Supersedes the 053 row 137f6250 (same recipe, INDB oil as written: F 12.5 g where the lab measured 6.5). Confidence C: anchor-only class, the moisture is the dry end of home upma until the cooking test.', 'founder 2026-11-13 (spec (i)1: keys upma, rava upma; (i)2: lab-fat oil at the lab-101 anchor)', '058')
  ON CONFLICT (id) DO NOTHING;

  -- §6 park every old key first: food_items_normalized_name_uidx is not deferrable
  UPDATE public.food_items fi
     SET parked_normalized_name = coalesce(fi.normalized_name, fi.parked_normalized_name), normalized_name = NULL
   WHERE fi.id IN (SELECT old_id FROM _plan058);

  -- §7 the new rows (verified, ownerless reference data; legacy per-serving columns mirror per 100 g)
  INSERT INTO public.food_items AS fi
    (id, external_id, source, name, calories, protein_g, carbs_g, fat_g, fiber_g, serving_size_g, created_by,
     normalized_name, calories_per_100g, protein_per_100g, carbs_per_100g, fat_per_100g, fiber_per_100g, fdc_id,
     portions, status, status_reason, status_changed_at, parked_normalized_name)
  SELECT nw.id, nw.external_id, nw.source, nw.name, nw.kcal, nw.protein, nw.carbs, nw.fat, nw.fiber, 100, NULL,
         nw.key, nw.kcal, nw.protein, nw.carbs, nw.fat, nw.fiber, nw.fdc_id,
         nw.portions, 'verified', nw.status_reason, now(), NULL
    FROM _new058 nw
  ON CONFLICT (id) DO UPDATE                -- re-apply after the down script: re-verify our own rolled-back row
     SET status = 'verified', status_reason = EXCLUDED.status_reason, status_changed_at = now(),
         normalized_name = EXCLUDED.normalized_name, parked_normalized_name = NULL
   WHERE fi.status = 'quarantined' AND fi.status_reason = 'reviewed:rollback_058';
  INSERT INTO public.food_derivation_items (food_item_id, derivation_id, is_canonical)
  SELECT nw.id, nw.derivation_id, nw.is_canonical FROM _new058 nw
  ON CONFLICT (food_item_id) DO NOTHING;

  -- §8 aliases: follow the old row to its successor; retire the ones whose words became exact keys
  UPDATE public.food_aliases fa SET food_item_id = a.new_target, note = a.note
    FROM _alias058 a WHERE a.kind = 'repoint' AND fa.alias = a.alias AND fa.food_item_id = a.expect_target;
  DELETE FROM public.food_aliases fa USING _alias058 a
   WHERE a.kind = 'retire' AND fa.alias = a.alias AND fa.food_item_id = a.expect_target;

  -- §9 memory follows its row to the successor, for same-food rows only: a pointer at a wrong_food_for_phrase row
  --    is never moved to another food (§3 proved the count equals the snapshot's, 0 there; §11(e) checks none is left)
  WITH m AS (
    UPDATE public.user_food_memory um SET food_item_id = p.new_id
      FROM _plan058 p WHERE um.food_item_id = p.old_id AND p.relation <> 'wrong_food_for_phrase'
    RETURNING p.old_id, p.new_id),
  logged AS (
    INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, successor_id, n_rows, reason)
    SELECT '058', 'memory_repoint', m.old_id, m.new_id, count(*), 'user_food_memory follows its row to the 058 successor'
      FROM m GROUP BY m.old_id, m.new_id RETURNING n_rows)
  UPDATE _state058 SET memory_moved = (SELECT coalesce(sum(n_rows), 0) FROM logged);

  -- §10 quarantine the old rows (facts untouched; §11 compares them with the backup)
  UPDATE public.food_items fi SET status = 'quarantined', status_reason = p.reason, status_changed_at = now()
    FROM _plan058 p WHERE fi.id = p.old_id;

  -- §10b portions (054's tables): the category of every new row, and its founder units
  INSERT INTO public.portion_category_map (food_item_id, category, note) SELECT food_item_id, category, note FROM _map058;
  INSERT INTO public.portion_units (id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default,
      is_unit_default, source, grade, confidence, source_ref, source_text, approved_by, status, evidence)
    SELECT id, food_item_id, NULL, NULL, unit, size, grams, ml, context, NULL, is_default, false, 'founder', 'F', 0.85,
           source_ref, source_text, approved_by, 'active', evidence FROM _pu058;   -- source_ref: each unit's approval date

  -- §10c the change log: one row per action, before/after values, never a user id
  INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, derivation_id, key, after, reason)
  SELECT '058', 'insert_derived', nw.id, nw.derivation_id, nw.key,
         jsonb_build_object('kcal', nw.kcal, 'protein', nw.protein, 'carbs', nw.carbs, 'fat', nw.fat, 'fiber', nw.fiber,
                            'portions', nw.portions, 'source', nw.source, 'name', nw.name), nw.status_reason
    FROM _new058 nw;
  INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, successor_id, derivation_id, key, relation,
                                         before, after, reason)
  SELECT '058', 'supersede', p.old_id, p.new_id, nw.derivation_id, p.expect_key, p.relation,
         jsonb_build_object('kcal', b.calories_per_100g, 'protein', b.protein_per_100g, 'carbs', b.carbs_per_100g,
                            'fat', b.fat_per_100g, 'fiber', b.fiber_per_100g, 'portions', b.portions, 'status', b.status,
                            'status_reason', b.status_reason),
         jsonb_build_object('kcal', nw.kcal, 'protein', nw.protein, 'carbs', nw.carbs, 'fat', nw.fat, 'fiber', nw.fiber,
                            'portions', nw.portions), p.reason
    FROM _plan058 p JOIN backup._backup_food_items_058 b ON b.id = p.old_id JOIN _new058 nw ON nw.id = p.new_id;
  INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, key, reason)
  SELECT '058', 'key_park', p.old_id, p.expect_key, 'key parked on the quarantined row' FROM _plan058 p;
  INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, key, reason)
  SELECT '058', 'key_take', nw.id, nw.key, nw.key_reason FROM _new058 nw;
  INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, successor_id, alias, reason)
  SELECT '058', 'alias_' || a.kind, a.expect_target, a.new_target, a.alias, a.note FROM _alias058 a;
  INSERT INTO public.food_value_changes (migration, change_kind, food_item_id, before, after, reason)
  SELECT '058', 'portion_change', nw.id, NULL, jsonb_build_object('portions', nw.portions, 'portion_units',
           (SELECT jsonb_agg(jsonb_build_object('unit', pu.unit, 'size', pu.size, 'grams', pu.grams, 'context', pu.context,
                                                'is_default', pu.is_default) ORDER BY pu.id) FROM _pu058 pu WHERE pu.food_item_id = nw.id),
           'category', (SELECT m.category FROM _map058 m WHERE m.food_item_id = nw.id)),
         'approved by ' || (SELECT min(pu.approved_by) FROM _pu058 pu WHERE pu.food_item_id = nw.id)
    FROM _new058 nw;
END
$apply$;

-- ── §11 Self-checks (any failure rolls back everything above) ───────────────────────────────────────
DO $chk$
DECLARE
  v_bad text; v_n bigint; v_m bigint; v_top record; pr record; v_ids uuid[];
BEGIN
  IF NOT (SELECT go FROM _state058) THEN
    RAISE NOTICE '058 ok: migrations-only replay, nothing to check';
    RETURN;
  END IF;
  -- (a) every new row passes rules v1 and carries the plan's numbers, key, portions and derivation
  SELECT string_agg(fi.name || ' ' || array_to_string(public.food_item_issues(fi.source, fi.name, fi.calories_per_100g,
           fi.protein_per_100g, fi.carbs_per_100g, fi.fat_per_100g, fi.fiber_per_100g), ','), '; ') INTO v_bad
    FROM _new058 nw JOIN public.food_items fi ON fi.id = nw.id
   WHERE public.food_item_issues(fi.source, fi.name, fi.calories_per_100g, fi.protein_per_100g, fi.carbs_per_100g,
                                 fi.fat_per_100g, fi.fiber_per_100g) <> '{}';
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: new rows fail rules v1: %', v_bad; END IF;
  SELECT string_agg(left(nw.id::text, 8) || ' ' || nw.key, ', ') INTO v_bad
    FROM _new058 nw LEFT JOIN public.food_items fi ON fi.id = nw.id
    LEFT JOIN public.food_derivation_items di ON di.food_item_id = nw.id
    LEFT JOIN public.food_derivations d ON d.id = nw.derivation_id
   WHERE fi.id IS NULL OR fi.status <> 'verified' OR fi.created_by IS NOT NULL OR fi.status_reason IS DISTINCT FROM nw.status_reason
      OR fi.normalized_name IS DISTINCT FROM nw.key OR fi.parked_normalized_name IS NOT NULL
      OR (fi.calories_per_100g, fi.protein_per_100g, fi.carbs_per_100g, fi.fat_per_100g, fi.fiber_per_100g)
         IS DISTINCT FROM (nw.kcal, nw.protein, nw.carbs, nw.fat, nw.fiber)
      OR (fi.calories, fi.protein_g, fi.carbs_g, fi.fat_g, fi.fiber_g) IS DISTINCT FROM (nw.kcal, nw.protein, nw.carbs, nw.fat, nw.fiber)
      OR fi.portions IS DISTINCT FROM nw.portions OR fi.source IS DISTINCT FROM nw.source OR fi.name IS DISTINCT FROM nw.name
      OR fi.external_id IS DISTINCT FROM nw.external_id OR fi.fdc_id IS NOT NULL
      OR di.derivation_id IS DISTINCT FROM nw.derivation_id OR di.is_canonical IS DISTINCT FROM nw.is_canonical
      OR (d.kcal, d.protein_g, d.carbs_g, d.fat_g, d.fiber_g) IS DISTINCT FROM (nw.kcal, nw.protein, nw.carbs, nw.fat, nw.fiber);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: new rows differ from the plan: %', v_bad; END IF;
  SELECT string_agg(d.variant_key, ', ') INTO v_bad FROM public.food_derivations d
   WHERE d.created_in = '058' AND d.method = 'recipe_recalc'
     AND abs(d.kcal - (4 * d.protein_g + 9 * d.fat_g + 4 * d.carbs_g + 2 * d.fiber_g)) > 0.5;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: kcal <> 4P + 9F + 4C + 2fib for: %', v_bad; END IF;
  -- the new derivations exist with the planned variant and numbers (a re-apply keeps the first copy: ON CONFLICT
  -- DO NOTHING; new numbers need a new calc version, which changes every id)
  SELECT string_agg(x.variant, ', ') INTO v_bad FROM (VALUES
      ('db23d70b-fc92-5026-8df7-cea4d4ee7116'::uuid, 'biryani_chicken_home', 'recipe_recalc', 162.34, 6.55, 19.06, 6.2, 2.05, 'FNP77:4P+9F+4CHOavl+2FIB'),
      ('4d684df3-36fb-55ed-a6fa-c83e58691ce8'::uuid, 'dal_makhani_home', 'recipe_recalc', 110.4, 4.74, 11.38, 4.38, 3.25, 'FNP77:4P+9F+4CHOavl+2FIB'),
      ('e91591d0-d598-5608-a27b-70e58b37bbd5'::uuid, 'pizza_cheese_sr173292', 'copy_reference', 266, 11.4, 33.3, 9.69, 2.3, 'USDA SR Legacy as published (Atwater specific factors); FDC 3-significant-figure presentation'),
      ('2c9d8f29-8a82-50e1-bc0c-822398e7b58b'::uuid, 'poha_home_labfat', 'recipe_recalc', 155.05, 4.14, 23.84, 4.23, 2.53, 'FNP77:4P+9F+4CHOavl+2FIB'),
      ('3232caa3-c89a-50de-81db-760686e2b816'::uuid, 'upma_rava_labfat', 'recipe_recalc', 222.24, 6.36, 31.45, 6.5, 6.25, 'FNP77:4P+9F+4CHOavl+2FIB')
    ) AS x(id, variant, method, kcal, protein, carbs, fat, fiber, energy_basis)
    LEFT JOIN public.food_derivations d ON d.id = x.id
   WHERE d.id IS NULL OR d.calc_version <> 'recalc_v2' OR d.variant_key <> x.variant OR d.method <> x.method OR d.created_in <> '058'
      OR d.energy_basis IS DISTINCT FROM x.energy_basis
      OR (d.kcal, d.protein_g, d.carbs_g, d.fat_g, d.fiber_g) IS DISTINCT FROM (x.kcal, x.protein, x.carbs, x.fat, x.fiber);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: derivations missing or with other numbers: %', v_bad; END IF;

  -- (b) old rows: quarantined, unkeyed (key parked), facts identical to the backup
  SELECT string_agg(left(p.old_id::text, 8), ', ') INTO v_bad
    FROM _plan058 p JOIN public.food_items f ON f.id = p.old_id JOIN backup._backup_food_items_058 b ON b.id = p.old_id
   WHERE f.status <> 'quarantined' OR f.normalized_name IS NOT NULL OR f.parked_normalized_name IS DISTINCT FROM p.expect_key
      OR f.status_reason IS DISTINCT FROM p.reason
      OR (f.source, f.name, f.external_id, f.created_by, f.calories_per_100g, f.protein_per_100g, f.carbs_per_100g, f.fat_per_100g, f.fiber_per_100g, f.calories, f.protein_g, f.carbs_g, f.fat_g, f.fiber_g, f.fdc_id, f.portions)
         IS DISTINCT FROM
         (b.source, b.name, b.external_id, b.created_by, b.calories_per_100g, b.protein_per_100g, b.carbs_per_100g, b.fat_per_100g, b.fiber_per_100g, b.calories, b.protein_g, b.carbs_g, b.fat_g, b.fiber_g, b.fdc_id, b.portions);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: old rows not cleanly quarantined: %', v_bad; END IF;

  -- (c) every superseded key is held by exactly its successor; the copy sources are untouched; the verified count adds up
  SELECT string_agg(p.expect_key || ' x' || c.n, ', ') INTO v_bad
    FROM _plan058 p CROSS JOIN LATERAL (SELECT count(*) n, min(fi.id::text) id FROM public.food_items fi
                                         WHERE fi.normalized_name = p.expect_key AND fi.status = 'verified') c
   WHERE c.n <> 1 OR c.id <> p.new_id::text;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: keys not held exactly once by their successor: %', v_bad; END IF;
  SELECT string_agg(left(s.id::text, 8), ', ') INTO v_bad
    FROM _src058 s JOIN public.food_items f ON f.id = s.id JOIN backup._backup_food_items_058 b ON b.id = s.id
   WHERE (f.status, f.status_reason, f.normalized_name, f.parked_normalized_name)
         IS DISTINCT FROM (b.status, b.status_reason, b.normalized_name, b.parked_normalized_name)
      OR (f.source, f.name, f.external_id, f.created_by, f.calories_per_100g, f.protein_per_100g, f.carbs_per_100g, f.fat_per_100g, f.fiber_per_100g, f.calories, f.protein_g, f.carbs_g, f.fat_g, f.fiber_g, f.fdc_id, f.portions) IS DISTINCT FROM (b.source, b.name, b.external_id, b.created_by, b.calories_per_100g, b.protein_per_100g, b.carbs_per_100g, b.fat_per_100g, b.fiber_per_100g, b.calories, b.protein_g, b.carbs_g, b.fat_g, b.fiber_g, b.fdc_id, b.portions);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: a copy source changed: %', v_bad; END IF;
  SELECT count(*) INTO v_n FROM public.food_items WHERE status = 'verified';
  SELECT (SELECT verified_before FROM _state058) + (SELECT count(*) FROM _new058) - (SELECT count(*) FROM _plan058) INTO v_m;
  IF v_n <> v_m THEN RAISE EXCEPTION '058: verified rows % (expected before + new - superseded = %)', v_n, v_m; END IF;
  -- keys, on the rows 058 owns only: none of its new, superseded or copy-source rows is verified without a key, and
  -- the number of key-less verified rows is unchanged (pending 055 imports its 11,986 rows with no key on purpose;
  -- its run-once guard needs none before it, which 058 therefore keeps when it goes first)
  SELECT string_agg(left(fi.id::text, 8), ', ') INTO v_bad FROM public.food_items fi
   WHERE fi.status = 'verified' AND fi.normalized_name IS NULL
     AND fi.id IN (SELECT id FROM _new058 UNION SELECT old_id FROM _plan058 UNION SELECT id FROM _src058);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: its rows verified without a key: %', v_bad; END IF;
  SELECT count(*) INTO v_n FROM public.food_items WHERE status = 'verified' AND normalized_name IS NULL;
  IF v_n <> (SELECT keyless_before FROM _state058) THEN RAISE EXCEPTION '058: key-less verified rows % (before: %)',
    v_n, (SELECT keyless_before FROM _state058); END IF;

  -- (d) aliases: as planned (retired ones gone); verified targets only; none equals a key; none disagrees with
  --     the key of its words
  SELECT string_agg(a.alias, ', ') INTO v_bad FROM _alias058 a LEFT JOIN public.food_aliases fa ON fa.alias = a.alias
   WHERE (a.kind = 'repoint' AND (fa.food_item_id IS DISTINCT FROM a.new_target OR fa.note IS DISTINCT FROM a.note))
      OR (a.kind = 'retire' AND fa.alias IS NOT NULL);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: aliases not as planned: %', v_bad; END IF;
  SELECT string_agg(fa.alias, ', ') INTO v_bad FROM public.food_aliases fa JOIN public.food_items fi ON fi.id = fa.food_item_id
   WHERE fi.status <> 'verified' OR fi.calories_per_100g IS NULL;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: aliases point at non-verified rows: %', v_bad; END IF;
  SELECT string_agg(fa.alias, ', ') INTO v_bad FROM public.food_aliases fa JOIN public.food_items fi ON fi.normalized_name = fa.alias;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: aliases equal to an exact key never fire: %', v_bad; END IF;
  SELECT string_agg(fa.alias || ' (key ' || fi.normalized_name || ')', ', ') INTO v_bad
    FROM public.food_aliases fa JOIN public.food_items fi ON fi.normalized_name IS NOT NULL AND fi.id <> fa.food_item_id
     AND (SELECT array_agg(x ORDER BY x) FROM regexp_split_to_table(fi.normalized_name, ' ') x)
       = (SELECT array_agg(x ORDER BY x) FROM regexp_split_to_table(fa.alias, ' ') x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: aliases disagree with the exact key of the same words: %', v_bad; END IF;

  -- (e) memory: nothing points at an old row; nothing points at a quarantined row anywhere (audit --check rule)
  SELECT count(*) INTO v_n FROM public.user_food_memory m WHERE m.food_item_id IN (SELECT old_id FROM _plan058);
  IF v_n > 0 THEN RAISE EXCEPTION '058: % memory pointers still target a superseded row', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.user_food_memory m JOIN public.food_items fi ON fi.id = m.food_item_id
   WHERE fi.status = 'quarantined';
  IF v_n > 0 THEN RAISE EXCEPTION '058: % memory pointers target quarantined rows', v_n; END IF;

  -- (f) history untouched: same fingerprints as at the start (the tables were SHARE-locked throughout)
  IF (SELECT ROW(e, d, s) FROM _fp058) IS DISTINCT FROM ROW(
    (SELECT count(*) || ':' || md5(coalesce(string_agg(concat_ws(':', id, food_item_id, quantity_g, calories, protein_g, carbs_g, fat_g, fiber_g), ',' ORDER BY id), '')) FROM public.food_entries),
    (SELECT count(*) || ':' || md5(coalesce(string_agg(concat_ws(':', id, total_calories, total_protein_g, total_carbs_g, total_fat_g), ',' ORDER BY id), '')) FROM public.daily_summaries),
    (SELECT count(*) || ':' || md5(coalesce(string_agg(id || entries::text, ',' ORDER BY id), '')) FROM public.saved_entries)) THEN
    RAISE EXCEPTION '058: food_entries / daily_summaries / saved_entries changed';
  END IF;

  -- (g) portions: each new row has exactly its founder units and its category; food_items.portions entries all
  --     have a founder unit (054's compare-and-swap invariant); no fdc-keyed unit can reach a new row
  SELECT string_agg(left(nw.id::text, 8) || ' ' || nw.key, ', ') INTO v_bad FROM _new058 nw
   WHERE (SELECT count(*) FROM public.portion_units pu WHERE pu.food_item_id = nw.id)
         <> (SELECT count(*) FROM _pu058 p JOIN public.portion_units pu ON pu.id = p.id AND pu.food_item_id = p.food_item_id
               AND pu.unit = p.unit AND pu.size = p.size AND pu.grams = p.grams AND pu.ml IS NOT DISTINCT FROM p.ml
               AND pu.context IS NOT DISTINCT FROM p.context AND pu.is_default = p.is_default AND pu.status = 'active'
               AND pu.source = 'founder' WHERE p.food_item_id = nw.id)
      OR (SELECT count(*) FROM _pu058 p WHERE p.food_item_id = nw.id) = 0
      OR (SELECT m.category FROM public.portion_category_map m WHERE m.food_item_id = nw.id)
         IS DISTINCT FROM (SELECT m.category FROM _map058 m WHERE m.food_item_id = nw.id)
      OR EXISTS (SELECT 1 FROM jsonb_array_elements(nw.portions) e WHERE NOT EXISTS (
           SELECT 1 FROM public.portion_units pu WHERE pu.food_item_id = nw.id AND pu.source = 'founder'
              AND pu.source_text = e->>'description' AND pu.grams = (e->>'gramWeight')::numeric))
      -- at most one no-context default (a key copy of a row with no food-level unit has none: its category serves it)
      OR (SELECT count(*) FROM public.portion_units pu WHERE pu.food_item_id = nw.id AND pu.is_default AND pu.context IS NULL) > 1
      OR (SELECT count(*) FROM public.portion_units pu WHERE pu.food_item_id = nw.id AND pu.is_default AND pu.context IS NULL)
         <> (SELECT count(*) FROM _pu058 p WHERE p.food_item_id = nw.id AND p.is_default AND p.context IS NULL)
      OR EXISTS (SELECT 1 FROM public.portion_units pu JOIN _pu058 p ON p.id = pu.id WHERE pu.food_item_id = nw.id
                  AND pu.source_ref IS DISTINCT FROM p.source_ref);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: portion rows not as planned: %', v_bad; END IF;
  SELECT string_agg(left(fi.id::text, 8), ', ') INTO v_bad FROM public.food_items fi JOIN _new058 nw ON nw.id = fi.id
    JOIN public.portion_units pu ON pu.fdc_id = fi.fdc_id;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '058: fdc-keyed portion units reach new rows: %', v_bad; END IF;

  -- (h) every approved phrase, normalized as macroResolver.ts normalizeName does, hits its row by exact key (fts
  --     and ranked modes: the fts read is .in(normalized_name).eq(status verified)); search_foods agrees
  FOR pr IN SELECT * FROM _phrase058 ORDER BY q LOOP
    IF btrim(regexp_replace(regexp_replace(lower(pr.q), '[^[:alnum:][:space:]]', ' ', 'g'), '\s+', ' ', 'g')) IS DISTINCT FROM pr.key THEN
      RAISE EXCEPTION '058: % does not normalize to %', pr.q, pr.key;
    END IF;
    v_ids := ARRAY(SELECT fi.id FROM public.food_items fi WHERE fi.normalized_name = btrim(regexp_replace(regexp_replace(lower(pr.q), '[^[:alnum:][:space:]]', ' ', 'g'), '\s+', ' ', 'g'))
                     AND fi.status = 'verified' AND fi.calories_per_100g IS NOT NULL);
    IF v_ids IS DISTINCT FROM ARRAY[pr.want] THEN
      RAISE EXCEPTION '058: exact key for % is %, expected %', pr.q, v_ids, pr.want;
    END IF;
    SELECT * INTO v_top FROM public.search_foods(pr.q, 1);
    IF v_top.id IS DISTINCT FROM pr.want OR v_top.match_kind IS DISTINCT FROM 'exact' THEN
      RAISE EXCEPTION '058: search_foods(%) top = % (%), expected % (exact)', pr.q, v_top.id, v_top.match_kind, pr.want;
    END IF;
  END LOOP;

  -- (i) what the push log shows: every phrase, its row, numbers and default serving; and fts / ranked probes
  FOR pr IN SELECT DISTINCT ON (p.key) p.key, fi.id, fi.name, fi.calories_per_100g AS kcal, fi.fat_per_100g AS fat,
                 coalesce((SELECT pu.unit || ' ' || pu.grams || ' g' FROM public.portion_units pu WHERE pu.food_item_id = fi.id
                   AND pu.is_default AND pu.context IS NULL), 'the ' || (SELECT m.category FROM public.portion_category_map m
                   WHERE m.food_item_id = fi.id) || ' category serving') AS serving
               FROM _phrase058 p JOIN public.food_items fi ON fi.id = p.want ORDER BY p.key LOOP
    RAISE NOTICE '058 key % -> % % (% kcal, F % /100 g; default %)', pr.key, left(pr.id::text, 8), pr.name, pr.kcal, pr.fat, pr.serving;
  END LOOP;
  FOR pr IN SELECT p.q, string_agg(s.name || ' ' || s.calories_per_100g || ' [' || s.match_kind || ']', ' | ') AS top
             FROM unnest(ARRAY['bhindi', 'bhindi subji', 'upma rava', 'cheese pizza', 'veg biryani', 'mutton biryani', 'kanda poha', 'rajma chawal']) AS p(q)
             CROSS JOIN LATERAL public.search_foods(p.q, 3) s GROUP BY p.q
  LOOP
    RAISE NOTICE '058 probe % -> %', pr.q, pr.top;
  END LOOP;
  RAISE NOTICE '058 ok: % new rows (% successors, % key copies, % new keys), % quarantined, % aliases retired, % repointed, % memory pointers moved, % portion units, % category-map rows; fingerprints unchanged',
    (SELECT count(*) FROM _new058), (SELECT count(*) FROM _new058 WHERE kind = 'successor'),
    (SELECT count(*) FROM _new058 WHERE kind = 'key_copy'),
    (SELECT count(*) FROM _new058 WHERE kind = 'new_key'), (SELECT count(*) FROM _plan058),
    (SELECT count(*) FROM _alias058 WHERE kind = 'retire'), (SELECT count(*) FROM _alias058 WHERE kind = 'repoint'),
    (SELECT memory_moved FROM _state058), (SELECT count(*) FROM _pu058), (SELECT count(*) FROM _map058);
  RAISE NOTICE '058 note: FDC 2706538 now has no verified row; pending 056 lists it in _need056: re-take scripts/usda/data/verified_fdc_snapshot.csv and regenerate 055/056 before they move into migrations/';
END
$chk$;

COMMENT ON COLUMN public.food_items.status_reason IS
  'rules_v1_pass | auto_050:<codes> | manual_050:<why> | unshared_050 | private | legacy_per_serving | auto_v1:<codes> (Phase 3 resolver) | rough_v1:<codes> (Phase 3 resolver: an AI guess still failing the rules after the retry, logged flagged and low-confidence and never remembered; an impossible guess is repaired first, a merely doubtful one is kept as given; <codes> are what the guess failed) | gate:<status> (guard downgrade) | reviewed:<note> (051+) | reviewed:053:recalc_v1:<variant> (053 recalculated/copied row; provenance in food_derivations) | reviewed:053:superseded:<relation>:<successor id8> | reviewed:053:quarantine_only:<why> | reviewed:rollback_053 (053 down script) | reviewed:058:recalc_v2:<variant> (058 batch-2 recalculated/copied row; provenance in food_derivations) | reviewed:058:superseded:<relation>:<successor id8> | reviewed:rollback_058 (058 down script)';

NOTIFY pgrst, 'reload schema';
